package com.expensetracker.web;

import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.Map;

/**
 * Serves files under /static/* from the classpath (src/main/resources/static).
 * Only the CSS lives here — HTML is generated by Java, charts are inline SVG.
 */
public class StaticHandler implements HttpHandler {

    private static final Map<String, String> CONTENT_TYPES = Map.of(
            ".css", "text/css; charset=UTF-8",
            ".png", "image/png",
            ".svg", "image/svg+xml",
            ".ico", "image/x-icon");

    @Override
    public void handle(HttpExchange ex) throws IOException {
        String path = ex.getRequestURI().getPath();
        // Path safety: strip "/static", reject anything with "..".
        String resource = path.substring("/static".length());
        if (resource.contains("..") || resource.isBlank()) {
            ex.sendResponseHeaders(404, -1);
            ex.close();
            return;
        }
        String classpathPath = "/static" + resource;
        try (InputStream in = getClass().getResourceAsStream(classpathPath)) {
            if (in == null) {
                ex.sendResponseHeaders(404, -1);
                ex.close();
                return;
            }
            String ext = resource.substring(resource.lastIndexOf('.'));
            ex.getResponseHeaders().set("Content-Type",
                    CONTENT_TYPES.getOrDefault(ext, "application/octet-stream"));
            ex.getResponseHeaders().set("Cache-Control", "public, max-age=3600");
            byte[] bytes = in.readAllBytes();
            ex.sendResponseHeaders(200, bytes.length);
            try (OutputStream os = ex.getResponseBody()) {
                os.write(bytes);
            }
        }
    }
}
